stageCss:
#stage .dl-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .dl-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .dl-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.4); color:var(--accent-1);
}
#stage .dl-mark svg{ width:25px; height:25px; }
#stage .dl-shop{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .dl-clock{
  margin-left:auto; flex-shrink:0; padding:7px 16px; border-radius:12px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.42);
  color:var(--accent-1); font-family:var(--font-mono); font-size:25px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .dl-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .dl-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .dl-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .dl-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .dl-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .dl-health.warn b{ color:var(--warn); }
#stage .dl-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .dl-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .dl-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .dl-body{ position:relative; flex:1; min-height:0; }
#stage .dl-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .dl-sc.on{ opacity:1; transform:none; }
#stage .dl-sc.whip{ animation:dl-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .dl-flow{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------- customer -- */
#stage .dl-cust{
  height:116px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .dl-cust.paid{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 46px rgba(63,185,80,.14); }
#stage .dl-cust.bad{ border-color:rgba(244,74,106,.55); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 46px rgba(244,74,106,.16); }
#stage .dl-avatar{
  width:60px; height:60px; border-radius:17px; flex-shrink:0; font-size:30px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .dl-cust-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .dl-cust-t b{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .dl-cust-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .dl-amt{
  margin-left:auto; flex-shrink:0; color:#fff;
  font-family:var(--font-mono); font-size:34px; font-weight:700; font-variant-numeric:tabular-nums;
}
#stage .dl-state{
  flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.4px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .dl-state.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .dl-state.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.16); color:var(--danger); }

/* ---------------------------------------------------------------- queue -- */
#stage .dl-q{
  height:168px; flex-shrink:0; display:flex; flex-direction:column; gap:12px;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.42);
}
#stage .dl-q-h{ display:flex; align-items:center; gap:13px; }
#stage .dl-q-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); color:var(--accent-1);
}
#stage .dl-q-ic svg{ width:27px; height:27px; }
#stage .dl-q-n{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.4px; }
#stage .dl-q-d{ margin-left:auto; display:flex; align-items:baseline; gap:8px; white-space:nowrap; }
#stage .dl-q-d b{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:27px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .dl-q-d i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .dl-track{
  position:relative; flex:1; min-height:0; display:flex; align-items:center; gap:10px;
  padding:0 14px; border-radius:16px; overflow:hidden;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
#stage .dl-msg{
  flex-shrink:0; display:flex; align-items:center; gap:8px;
  padding:11px 14px; border-radius:12px; white-space:nowrap;
  background:rgba(34,211,238,.1); border:1.5px solid rgba(34,211,238,.42);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  animation:msd-pop .3s cubic-bezier(.22,1,.36,1);
}
#stage .dl-msg b{ color:#fff; }
#stage .dl-msg span{ color:var(--accent-cyan); }
/* Locked, not deleted: a dashed outline is the whole of PeekLock in one style. */
#stage .dl-msg.inflight{
  border-style:dashed; border-color:rgba(240,166,74,.7);
  background:rgba(240,166,74,.1); opacity:.72;
}
#stage .dl-msg.inflight span{ color:var(--warn); }
#stage .dl-msg.poison{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.12); }
#stage .dl-msg.poison span{ color:var(--danger); }
#stage .dl-msg.back{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }
#stage .dl-msg.pull{ animation:dl-pull .34s ease-in forwards; }

/* ---------------------------------------------- lock / redelivery / count -- */
#stage .dl-mid{
  height:74px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
}
#stage .dl-lock, #stage .dl-cnt{
  display:flex; align-items:center; gap:9px; padding:8px 16px; border-radius:12px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7);
  color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:600;
  transition:border-color .3s ease, color .3s ease, background .3s ease;
}
#stage .dl-lock b, #stage .dl-cnt b{ color:#fff; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .dl-lock.hot{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.12); color:var(--warn); }
#stage .dl-lock.hot b{ color:var(--warn); }
#stage .dl-lock.dead{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.14); color:var(--danger); }
#stage .dl-lock.dead b{ color:var(--danger); }
#stage .dl-cnt{ margin-left:auto; }
#stage .dl-cnt.hot{ border-color:rgba(240,166,74,.6); color:var(--warn); }
#stage .dl-cnt.hot b{ color:var(--warn); font-size:24px; }
#stage .dl-cnt.max{ border-color:rgba(244,74,106,.7); background:rgba(244,74,106,.14); color:var(--danger); animation:dl-alert .8s ease-in-out infinite; }
#stage .dl-cnt.max b{ color:var(--danger); font-size:24px; }
#stage .dl-arc{
  padding:8px 16px; border-radius:12px; white-space:nowrap; opacity:0;
  border:1.5px solid rgba(58,160,255,.5); background:rgba(58,160,255,.14); color:var(--accent-1);
  font-family:var(--font-mono); font-size:20px; font-weight:700;
  transition:opacity .2s ease;
}
#stage .dl-arc.on{ opacity:1; animation:msd-punch .42s cubic-bezier(.22,1,.36,1); }

/* -------------------------------------------------- worker and gateway --- */
#stage .dl-row{ flex:1; min-height:0; display:flex; gap:14px; align-items:stretch; }
#stage .dl-wk, #stage .dl-gw{
  flex:1; display:flex; flex-direction:column; gap:11px; justify-content:center;
  padding:18px 20px; border-radius:24px; min-width:0;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .dl-wk.busy{ border-color:rgba(58,160,255,.55); box-shadow:0 0 0 1px rgba(58,160,255,.24), 0 0 42px rgba(58,160,255,.14); }
#stage .dl-wk.ok, #stage .dl-gw.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 42px rgba(63,185,80,.14); }
#stage .dl-wk.bad, #stage .dl-gw.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.26), 0 0 50px rgba(244,74,106,.18);
  animation:dl-alert 1s ease-in-out infinite;
}
#stage .dl-gw.slow{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.24), 0 0 46px rgba(240,166,74,.16); }
#stage .dl-card-h{ display:flex; align-items:center; gap:12px; }
#stage .dl-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
}
#stage .dl-ic svg{ width:26px; height:26px; }
#stage .dl-wk.busy .dl-ic svg{ animation:msd-spin 2.6s linear infinite; }
#stage .dl-wk.ok .dl-ic, #stage .dl-gw.ok .dl-ic{ background:rgba(63,185,80,.16); color:var(--success); }
#stage .dl-wk.bad .dl-ic, #stage .dl-gw.bad .dl-ic{ background:rgba(244,74,106,.16); color:var(--danger); }
#stage .dl-gw.slow .dl-ic{ background:rgba(240,166,74,.16); color:var(--warn); }
#stage .dl-card-h b{ color:#fff; font-family:var(--font-mono); font-size:22px; font-weight:700; white-space:nowrap; }
#stage .dl-card-s{
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .dl-card-c{
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .dl-wk.ok .dl-card-s, #stage .dl-gw.ok .dl-card-s{ color:var(--success); }
#stage .dl-wk.bad .dl-card-s, #stage .dl-gw.bad .dl-card-s{ color:var(--danger); }
#stage .dl-gw.slow .dl-card-s{ color:var(--warn); }

#stage .dl-link{
  width:64px; flex-shrink:0; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:9px;
}
#stage .dl-link i{
  display:block; width:26px; height:4px; border-radius:2px;
  background:var(--accent-cyan); box-shadow:0 0 12px rgba(34,211,238,.5);
  animation:dl-send 1s linear infinite;
}
#stage .dl-link i:nth-child(2){ animation-delay:.2s; }
#stage .dl-link i:nth-child(3){ animation-delay:.4s; }
#stage .dl-link.dead i{ background:var(--danger); box-shadow:0 0 12px rgba(244,74,106,.5); animation:none; opacity:.5; }

/* ------------------------------------------------------ dead-letter queue -- */
#stage .dl-dlq{
  height:150px; flex-shrink:0; display:flex; flex-direction:column; gap:11px;
  padding:15px 20px; border-radius:24px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.42; filter:saturate(.3);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, box-shadow .3s ease, background .3s ease;
}
#stage .dl-dlq.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.6);
  background:rgba(244,74,106,.07);
  box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 50px rgba(244,74,106,.14);
}
#stage .dl-dlq-h{ display:flex; align-items:center; gap:13px; }
#stage .dl-dlq-ic{
  width:44px; height:44px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.12); border:1.5px solid rgba(244,74,106,.3);
}
#stage .dl-dlq-n{ color:#fff; font-family:var(--font-mono); font-size:22px; font-weight:700; white-space:nowrap; }
#stage .dl-dlq-d{ margin-left:auto; display:flex; align-items:baseline; gap:8px; white-space:nowrap; }
#stage .dl-dlq-d b{ color:var(--danger); font-family:var(--font-mono); font-size:26px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .dl-dlq-d i{ color:var(--text-dim); font-size:17px; font-weight:600; font-style:normal; }
#stage .dl-dlq-b{
  flex:1; min-height:0; display:flex; align-items:center; gap:10px;
  padding:0 14px; border-radius:14px; overflow:hidden;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border);
}
#stage .dl-dlq-e{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; white-space:nowrap; }
#stage .dl-dead{
  display:flex; align-items:center; gap:10px; white-space:nowrap;
  padding:10px 14px; border-radius:12px;
  background:rgba(244,74,106,.14); border:1.5px solid rgba(244,74,106,.55); color:#ffd0d9;
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  animation:dl-land .42s cubic-bezier(.22,1,.36,1);
}
#stage .dl-dead b{ color:#fff; }
#stage .dl-dead span{ color:var(--danger); }

/* ---------------------------------------------------------------- strip -- */
#stage .dl-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .dl-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .dl-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .dl-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .dl-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .dl-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .dl-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ========================= SCENE 2 · SPLIT-SCREEN ====================== */
#stage .dl-split{ display:flex; gap:16px; height:100%; }
#stage .dl-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  padding:26px 20px; border-radius:28px; text-align:center;
}
#stage .dl-col.bad{
  background:radial-gradient(circle at 50% 0%, rgba(244,74,106,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(244,74,106,.55);
  animation:dl-alert 1.1s ease-in-out infinite;
}
#stage .dl-col.good{
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(63,185,80,.5);
}
#stage .dl-col-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.6px; }
#stage .dl-col.bad .dl-col-h{ color:var(--danger); }
#stage .dl-col.good .dl-col-h{ color:var(--success); }
#stage .dl-col-ic{ font-size:66px; line-height:1; }
#stage .dl-col.bad .dl-col-ic{ animation:msd-shake .6s ease-in-out infinite; }
#stage .dl-col.good .dl-col-ic{ animation:msd-breathe 2.2s ease-in-out infinite; }
#stage .dl-col-n{
  color:#fff; font-family:var(--font-mono); font-size:70px; font-weight:800;
  line-height:1; font-variant-numeric:tabular-nums; letter-spacing:-2px;
}
#stage .dl-col-l{ color:var(--text-dim); font-size:20px; font-weight:600; }
#stage .dl-col-list{ width:100%; display:flex; flex-direction:column; gap:9px; margin-top:6px; }
#stage .dl-mini{
  padding:11px 12px; border-radius:11px; white-space:nowrap;
  background:rgba(244,74,106,.12); border:1px solid rgba(244,74,106,.35); color:#ffd0d9;
  font-family:var(--font-mono); font-size:17px; font-weight:600;
}
#stage .dl-mini.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.35); color:#bff0c4; }
#stage .dl-col-x{
  width:100%; margin-top:6px; padding:12px 10px; border-radius:14px; white-space:nowrap;
  background:rgba(244,74,106,.16); border:1.5px solid rgba(244,74,106,.5); color:var(--danger);
  font-family:var(--font-mono); font-size:20px; font-weight:700;
}
#stage .dl-col-x.ok{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.5); color:var(--success); }

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .dl-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .dl-badge{
  width:132px; height:132px; border-radius:36px; font-size:66px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.28), rgba(34,211,238,.14));
  border:2px solid rgba(58,160,255,.6);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 80px rgba(58,160,255,.34);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .dl-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:5px; }
#stage .dl-fin-h{ color:#fff; font-size:58px; font-weight:900; line-height:1.14; letter-spacing:-1.6px; }
#stage .dl-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .dl-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .dl-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .dl-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:840px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:26px; font-weight:700; line-height:1.35;
}
#stage .dl-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes dl-send{
  0%{ transform:translateX(-10px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateX(12px); opacity:0; }
}
@keyframes dl-pull{
  0%{ transform:translateY(0) scale(1); opacity:1; }
  100%{ transform:translateY(-40px) scale(.82); opacity:0; }
}
@keyframes dl-land{
  0%{ transform:translateY(-46px) scale(.8); opacity:0; }
  70%{ transform:translateY(4px) scale(1.03); opacity:1; }
  100%{ transform:none; opacity:1; }
}
@keyframes dl-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes dl-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

