DL.fmt = function(n){
  n = Math.round(n);
  var s = String(n), out = '', c = 0;
  for(var i = s.length - 1; i >= 0; i--){
    out = s.charAt(i) + out; c++;
    if(c % 3 === 0 && i > 0) out = ',' + out;
  }
  return out;
};
DL.ramp = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = DL.fmt(from + (to - from) * p);
    if(p >= 1) clearInterval(id);
  });
};
// Fills the visible queue. The head is the message the reel follows; the
// two behind it are there so "still waiting" has something to point at.
DL.fill = function(head, headCls){
  var track = MSD.q('#dl-track');
  track.innerHTML = '';
  var ids = [head, '#90219', '#90220'];
  ids.forEach(function(id, i){
    var el = document.createElement('div');
    el.className = 'dl-msg' + (i === 0 && headCls ? ' ' + headCls : '');
    el.innerHTML = '<b>' + id + '</b><span>' + (i === 0 ? 'in flight' : 'waiting') + '</span>';
    track.appendChild(el);
  });
};
